/* Token Radar — dark neon-fin theme.
   Palette: deep sea navy base, neon cyan for value, coral for falling, mint for growth. */
:root {
  --bg: #060b14;
  --bg-2: #0a1220;
  --panel: #0d1626;
  --panel-2: #111d31;
  --line: #1c2c45;
  --line-2: #25395c;
  --text: #dbe7f6;
  --muted: #7d93b3;
  --cyan: #35e0d2;
  --cyan-dim: rgba(53, 224, 210, 0.14);
  --mint: #4ade80;
  --coral: #fb7185;
  --amber: #fbbf24;
  --violet: #a78bfa;
  --mono: 'SFMono-Regular', ui-monospace, 'Cascadia Mono', Menlo, Consolas, monospace;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text); font-family: var(--sans); font-size: 14px; }
body {
  background:
    radial-gradient(1100px 500px at 85% -8%, rgba(53, 224, 210, 0.07), transparent 60%),
    radial-gradient(900px 480px at -10% 12%, rgba(167, 139, 250, 0.06), transparent 55%),
    var(--bg);
  min-height: 100vh;
}
.skip { position: absolute; left: -9999px; }
.skip:focus { left: 8px; top: 8px; background: var(--panel); padding: 8px 12px; border-radius: 8px; }
main { max-width: 1220px; margin: 0 auto; padding: 20px 20px 64px; }

/* ---------- header ---------- */
.hero { display: flex; flex-wrap: wrap; align-items: baseline; gap: 12px; padding: 18px 0 4px; }
.hero h1 { margin: 0; font-size: 26px; letter-spacing: -0.02em; font-weight: 800; }
.hero h1 .fin { color: var(--cyan); text-shadow: 0 0 18px rgba(53, 224, 210, 0.45); }
.hero .sub { color: var(--muted); font-size: 13px; }
.statline { display: flex; flex-wrap: wrap; gap: 10px; margin: 14px 0 4px; }
.stat {
  background: linear-gradient(180deg, var(--panel), var(--bg-2));
  border: 1px solid var(--line); border-radius: 12px;
  padding: 10px 14px; min-width: 132px;
}
.stat .k { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; }
.stat .v { font-family: var(--mono); font-size: 17px; font-weight: 700; margin-top: 3px; color: var(--cyan); }
.stat .v.plain { color: var(--text); }

/* ---------- model card ---------- */
.modelcard {
  border: 1px solid var(--line-2); border-radius: 14px; margin: 16px 0;
  background: linear-gradient(180deg, rgba(53,224,210,0.05), transparent 65%), var(--panel);
  padding: 14px 16px;
}
.modelcard h2 { margin: 0 0 6px; font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--cyan); }
.modelcard p { margin: 4px 0; color: var(--muted); font-size: 13px; line-height: 1.55; }
.modelcard code { font-family: var(--mono); color: var(--amber); font-size: 12px; background: var(--cyan-dim); padding: 1px 6px; border-radius: 6px; }
.modelcard .formula { font-family: var(--mono); font-size: 12.5px; color: var(--text); background: #09101c; border: 1px solid var(--line); border-radius: 10px; padding: 10px 12px; margin: 10px 0; overflow-x: auto; white-space: pre; }

/* ---------- controls ---------- */
.controls { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 14px 0; }
.controls input[type="search"] {
  background: var(--panel-2); border: 1px solid var(--line-2); color: var(--text);
  border-radius: 10px; padding: 9px 13px; font-size: 14px; min-width: 240px; outline: none;
}
.controls input[type="search"]:focus { border-color: var(--cyan); box-shadow: 0 0 0 3px rgba(53,224,210,0.12); }
.controls select {
  background: var(--panel-2); border: 1px solid var(--line-2); color: var(--text);
  border-radius: 10px; padding: 9px 10px; font-size: 13px; outline: none;
}
.controls .chip {
  border: 1px solid var(--line-2); background: transparent; color: var(--muted);
  border-radius: 999px; padding: 7px 13px; font-size: 12.5px; cursor: pointer;
}
.controls .chip:hover { color: var(--text); border-color: var(--cyan); }
.controls .chip.on { background: var(--cyan-dim); color: var(--cyan); border-color: var(--cyan); }
.controls .count { color: var(--muted); font-size: 12.5px; margin-left: auto; }

/* ---------- board table ---------- */
.tablewrap { border: 1px solid var(--line); border-radius: 14px; overflow: auto; background: var(--panel); }
table { border-collapse: collapse; width: 100%; min-width: 860px; }
thead th {
  position: sticky; top: 0; background: var(--panel-2); color: var(--muted);
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.07em;
  padding: 10px 12px; text-align: left; cursor: pointer; user-select: none; white-space: nowrap;
  border-bottom: 1px solid var(--line-2);
}
thead th:hover { color: var(--cyan); }
thead th .arrow { color: var(--cyan); margin-left: 4px; }
tbody td { padding: 9px 12px; border-bottom: 1px solid var(--line); font-size: 13.5px; white-space: nowrap; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel-2); }
tbody tr.watch { box-shadow: inset 3px 0 0 var(--cyan); }
td.num { font-family: var(--mono); text-align: right; }
td.rank { font-family: var(--mono); color: var(--muted); font-weight: 700; }
td.imp { font-family: var(--mono); color: var(--cyan); font-weight: 700; }
td.name { font-weight: 600; }
td.name .slug { color: var(--muted); font-weight: 400; font-size: 11.5px; margin-left: 6px; font-family: var(--mono); }
.cat { display: inline-block; font-size: 11px; border-radius: 999px; padding: 2px 9px; border: 1px solid var(--line-2); color: var(--muted); }
.cat.lending, .cat.cdp { color: var(--violet); border-color: rgba(167,139,250,0.4); }
.cat.dexs, .cat.yield { color: var(--mint); border-color: rgba(74,222,128,0.4); }
.cat.derivatives, .cat.basis-trading { color: var(--amber); border-color: rgba(251,191,36,0.4); }
.cat.rwa { color: var(--cyan); border-color: rgba(53,224,210,0.4); }
.up { color: var(--mint); } .down { color: var(--coral); }
.watchbadge { font-size: 10px; color: var(--cyan); border: 1px solid var(--cyan); border-radius: 999px; padding: 1px 7px; margin-left: 8px; letter-spacing: 0.06em; }

/* ---------- detail drawer ---------- */
.drawer {
  position: fixed; top: 0; right: 0; height: 100vh; width: min(520px, 94vw);
  background: var(--bg-2); border-left: 1px solid var(--line-2);
  box-shadow: -24px 0 60px rgba(0,0,0,0.55);
  overflow-y: auto; padding: 22px; z-index: 30;
}
.drawer .close {
  position: absolute; top: 14px; right: 16px; background: var(--panel-2); color: var(--muted);
  border: 1px solid var(--line-2); border-radius: 10px; padding: 6px 12px; cursor: pointer; font-size: 13px;
}
.drawer .close:hover { color: var(--cyan); border-color: var(--cyan); }
.drawer h2 { margin: 2px 0 2px; font-size: 21px; }
.drawer .slugline { font-family: var(--mono); color: var(--muted); font-size: 12px; margin-bottom: 12px; }
.drawer .bigimp { font-family: var(--mono); font-size: 30px; font-weight: 800; color: var(--cyan); text-shadow: 0 0 22px rgba(53,224,210,0.4); }
.drawer .biglab { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.09em; }
.facts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: 14px 0; }
.fact { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 9px 11px; }
.fact .k { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; }
.fact .v { font-family: var(--mono); font-size: 14px; margin-top: 3px; }
.mults { margin: 12px 0; }
.mults .mrow { display: flex; justify-content: space-between; padding: 5px 2px; border-bottom: 1px dashed var(--line); font-size: 13px; }
.mults .mrow .mv { font-family: var(--mono); color: var(--amber); }
.sparkwrap { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px; margin: 12px 0; }
.sparkwrap .t { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.07em; margin-bottom: 6px; }
.steps h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--cyan); margin: 18px 0 8px; }
.step { display: flex; gap: 10px; padding: 10px 0; border-bottom: 1px solid var(--line); font-size: 13px; line-height: 1.5; }
.step .n {
  flex: 0 0 24px; height: 24px; border-radius: 50%; background: var(--cyan-dim); color: var(--cyan);
  font-family: var(--mono); font-weight: 700; font-size: 12px; display: flex; align-items: center; justify-content: center;
}
.step .meta { color: var(--muted); font-size: 12px; margin-top: 3px; }
.step .meta .cost { color: var(--amber); }
.scrim { position: fixed; inset: 0; background: rgba(3,6,12,0.6); z-index: 25; }

/* ---------- live section ---------- */
.live h2 { color: var(--violet); font-size: 14px; text-transform: uppercase; letter-spacing: 0.08em; margin: 26px 0 10px; }
.live table { min-width: 640px; }
.live tbody tr { cursor: default; }
.footnote { color: var(--muted); font-size: 12px; margin-top: 22px; line-height: 1.6; }
.empty { color: var(--muted); padding: 26px; text-align: center; }
@media (max-width: 640px) { .facts { grid-template-columns: 1fr; } main { padding: 14px 12px 48px; } }

.bar { width: 120px; height: 6px; border-radius: 999px; background: #16233a; overflow: hidden; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, #1f9e94, var(--cyan)); box-shadow: 0 0 10px rgba(53,224,210,0.5); }
tr.watch td.imp::before { content: ''; }
.up, .v.up { color: var(--mint); }
.down, .v.down { color: var(--coral); }
